SELECT S.BIG_ROLL_CODE, T.CX_MACHINE_CODE, T.UNIT_CONSUME, IFNULL(S.STOCK_QTY, 0) TODAY_STOCK, CASE WHEN IFNULL(S.STOCK_QTY, 0) > IFNULL(T.USE_NUM, 0) THEN IFNULL(S.STOCK_QTY, 0) - IFNULL(T.USE_NUM, 0) ELSE 0 END STOCK_QTY, IFNULL(T.USE_NUM, 0) CX_USE_QTY FROM (
) S LEFT JOIN (
) T ON S.BIG_ROLL_CODE = T.BIG_ROLL_CODE

SELECT CI.CORD_SPEC BIG_ROLL_CODE /*帘线规格*/ FROM T_CX_SCHEDULE_RESULT R INNER JOIN T_PRODUCT_CONSTRUCTION_INFO CI ON R.EMBRYO_CODE = CI.EMBRYO_CODE AND R.BOM_DATA_VERSION = CI.EMBRYO_VERSION INNER JOIN T_XWYY_PARAMS P ON P.PARAM_CODE = 'CLOSE_OUT_SPEC_REMARK' AND P.DEL_FLAG = '0' AND P.PARAM_VALUE IS NOT NULL WHERE R.SCHEDULE_DATE = #{scheduleDate} AND R.DEL_FLAG = '0' AND CI.DEL_FLAG = '0' AND CI.TIRE_FABRIC_CODE1 IS NOT NULL
/* 仅对投产阶段的规格排产 */ AND CI.PRODUCTION_STAGE = '0'
AND NOT EXISTS (SELECT 1 FROM T_CX_SCHEDULE_RESULT R2 LEFT JOIN T_PRODUCT_CONSTRUCTION_INFO CI2 ON R2.EMBRYO_CODE = CI2.EMBRYO_CODE AND R2.BOM_DATA_VERSION = CI2.EMBRYO_VERSION WHERE R2.SCHEDULE_DATE = R.SCHEDULE_DATE AND CI2.ORIGINAL_LINE_CODE = CI.ORIGINAL_LINE_CODE AND R2.DEL_FLAG = '0' AND CI2.DEL_FLAG = '0' AND CI2.TIRE_FABRIC_CODE1 IS NOT NULL
/* 仅对投产阶段的规格排产 */ AND CI2.PRODUCTION_STAGE = '0'
AND NOT REGEXP_LIKE(IFNULL(R2.CLASS1_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS1_ANALYSIS_INPUT, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS2_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS2_ANALYSIS_INPUT, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS3_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS3_ANALYSIS_INPUT, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS4_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS4_ANALYSIS_INPUT, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS5_ANALYSIS, ' '), P.PARAM_VALUE) AND NOT REGEXP_LIKE(IFNULL(R2.CLASS5_ANALYSIS_INPUT, ' '), P.PARAM_VALUE)) GROUP BY CI.CORD_SPEC

